void BFS(
    int startNode,
    vector adjList[],
    int V
) {
    vector visited(V, false);
    queue q;
    visited[startNode] = true;
    q.push(startNode);
    while (!q.empty()) {
        int current = q.front();
        q.pop();
        cout << current << " ";
        for (int neighbor : adjList[current]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                q.push(neighbor);
            }
        }
    }
}

