void DFS(
    int startNode,
    vector adjList[],
    int V
) {
    vector visited(V, false);
    stack s;
    s.push(startNode);
    while (!s.empty()) {
        int current = s.top();
        s.pop();
        if (visited[current]) {
            continue;
        }
        visited[current] = true;
        cout << current << " ";
        for (
            int i = adjList[current].size() - 1;
            i >= 0;
            i--
        ) {
            int neighbor = adjList[current][i];
            if (!visited[neighbor]) {
                s.push(neighbor);
            }
        }
    }
}

