function twoSum(nums, target) {
    const map = new Map();
    for (let i = 0; i < nums.length; i++) {
        const complement =
            target - nums[i];
        if (map.has(complement)) {
            return [
                map.get(complement),
                i
            ];
        }
        map.set(nums[i], i);
    }
    return [];
}
console.log(
    twoSum([2, 7, 11, 15], 9)
);
// [0, 1]

function hasDuplicate(arr) {
    const set = new Set();
    for (const num of arr) {
        if (set.has(num)) {
            return true;
        }
        set.add(num);
    }
    return false;
}

